/* From Uiverse.io by Yaya12085 - Tags: sign-in, form */
.__UIV_SCOPE__ .form {
  background-color: #fff;
  display: block;
  padding: 1rem;
  max-width: 350px;
  border-radius: 0.5rem;
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

.__UIV_SCOPE__ .form-title {
  font-size: 1.25rem;
  line-height: 1.75rem;
  font-weight: 600;
  text-align: center;
  color: #000;
}

.__UIV_SCOPE__ .input-container {
  position: relative;
}

.__UIV_SCOPE__ .input-container input, .__UIV_SCOPE__ .form button {
  outline: none;
  border: 1px solid #e5e7eb;
  margin: 8px 0;
}

.__UIV_SCOPE__ .input-container input {
  background-color: #fff;
  padding: 1rem;
  padding-right: 3rem;
  font-size: 0.875rem;
  line-height: 1.25rem;
  width: 300px;
  border-radius: 0.5rem;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.__UIV_SCOPE__ .input-container span {
  display: grid;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  padding-left: 1rem;
  padding-right: 1rem;
  place-content: center;
}

.__UIV_SCOPE__ .input-container span svg {
  color: #9CA3AF;
  width: 1rem;
  height: 1rem;
}

.__UIV_SCOPE__ .submit {
  display: block;
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
  background-color: #4F46E5;
  color: #ffffff;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 500;
  width: 100%;
  border-radius: 0.5rem;
  text-transform: uppercase;
}

.__UIV_SCOPE__ .signup-link {
  color: #6B7280;
  font-size: 0.875rem;
  line-height: 1.25rem;
  text-align: center;
}

.__UIV_SCOPE__ .signup-link a {
  text-decoration: underline;
}
